static std::shared_ptr<ncnn_llm_gpt_ctx> create_ctx(int sconv_cnt, int gdr_cnt) {
    if (sconv_cnt > 0 || gdr_cnt > 0) {
        return std::make_shared<qwen3_5_ctx>();
